(n, w, l) = [int(i) for i in input().split(' ')]
h = [None] * n
r = [None] * n
for i in range(n):
	(h[i], r[i]) = [int(i) for i in input().split(' ')]
lo = 0
hi = 10 ** 30
ans = hi
while lo <= hi:
	mid = (lo + hi) // 2
	sum = 0
	for i in range(n):
		if h[i] + r[i] * mid >= l:
			sum += h[i] + r[i] * mid
	if sum >= w:
		ans = mid
		hi = mid - 1
	else:
		lo = mid + 1
print(ans)
